//! GSUB differential test: every text in test/shaping/harfbuzz.txt must
//! shape to the glyph IDs HarfBuzz produced for it (generated by
//! scripts/gen_shaping_reference.py). Shaping goes through
//! markUnicodeCharsUsed, the path rendering uses.

const std = @import("std");
const EmbeddedFont = @import("embedded.zig").EmbeddedFont;
const opentype = @import("opentype.zig");

const reference_path = "test/shaping/harfbuzz.txt";

fn parseGlyphs(allocator: std.mem.Allocator, list: []const u8) ![]u16 {
    var out: std.ArrayListUnmanaged(u16) = .empty;
    errdefer out.deinit(allocator);
    var it = std.mem.tokenizeScalar(u8, list, ' ');
    while (it.next()) |tok| try out.append(allocator, try std.fmt.parseInt(u16, tok, 10));
    return out.toOwnedSlice(allocator);
}

test "GSUB shaping matches HarfBuzz (test/shaping/harfbuzz.txt)" {
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const data = try std.Io.Dir.cwd().readFileAlloc(io, reference_path, allocator, .limited(16 << 20));
    defer allocator.free(data);

    var font: ?*EmbeddedFont = null;
    defer if (font) |f| f.deinit();
    var font_path: []const u8 = "";
    var features: []const u8 = "";
    var checked: usize = 0;
    var mismatches: usize = 0;

    var lines = std.mem.splitScalar(u8, data, '\n');
    while (lines.next()) |line| {
        if (line.len == 0) continue;
        if (std.mem.startsWith(u8, line, "font ")) {
            if (font) |f| f.deinit();
            font = null;
            font_path = line[5..];
            font = try EmbeddedFont.fromFile(io, allocator, font_path);
            continue;
        }
        if (std.mem.startsWith(u8, line, "features")) {
            features = std.mem.trim(u8, line[8..], " ");
            var it = std.mem.tokenizeScalar(u8, features, ' ');
            while (it.next()) |t| {
                const feature = opentype.Feature.fromTag(std.mem.readInt(u32, t[1..5], .big)) orelse {
                    std.debug.print("unknown feature {s}\n", .{t});
                    return error.UnknownFeature;
                };
                font.?.setFeature(feature, t[0] == '+');
            }
            continue;
        }
        const tab = std.mem.indexOfScalar(u8, line, '\t') orelse return error.BadReferenceLine;
        const text = line[0..tab];
        const expected = try parseGlyphs(allocator, line[tab + 1 ..]);
        defer allocator.free(expected);
        const actual = try font.?.markUnicodeCharsUsed(text, allocator);
        defer allocator.free(actual);
        checked += 1;
        if (!std.mem.eql(u16, expected, actual)) {
            mismatches += 1;
            std.debug.print("\n{s} [{s}] \"{s}\"\n  harfbuzz: {any}\n  platen:   {any}\n", .{ font_path, features, text, expected, actual });
        }
    }
    if (mismatches > 0) std.debug.print("\n{d} of {d} texts shape differently from HarfBuzz\n", .{ mismatches, checked });
    try std.testing.expect(checked > 0);
    try std.testing.expectEqual(@as(usize, 0), mismatches);
}
